define_pass(ast):                      # pass 1: collect declarations
    enter_scope(node)                  # blocks/functions/classes push a scope
    define(symbol)                     # duplicate in this scope -> diagnostic
    leave_scope()                      # keep the scope if later phases need it
resolve_pass(ast):                     # pass 2: bind every use
    for use in identifier_uses(node):
        scope, sym = lookup_innermost_outward(use.name)
        if sym is None: report(use.pos, 'unresolved')
        else: bind(use, distance(scope) or sym)
